create_dashboard_banner.code:
use WebCommander\Resources\DashboardBanners\DashboardBanners;

$response = DashboardBanners::createDashboardBanner($client, [
    'key' => 'spring_sale',
    'title' => 'Spring sale',
    'description' => 'Ends Friday.',
    'tags' => ['Sales'],
    'icon' => 'tag',
    'learn_more' => ['action' => 'open_link', 'label' => 'Learn more', 'url' => 'https://example.com/spring-sale'],
]);

echo $response->map['key'], ' at position ', $response->map['position'], PHP_EOL;

patch_dashboard_banner.code:
use WebCommander\Resources\DashboardBanners\DashboardBanners;

$response = DashboardBanners::patchDashboardBanner($client, 'spring_sale', ['title' => 'Spring sale ends today', 'active' => false]);

echo $response->map['title'], $response->map['active'] ? '' : ' (inactive)', PHP_EOL;
